package in.finseq.insurance;
import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.os.*;import android.os.ParcelFileDescriptor;import android.view.*;import android.widget.*;import java.io.*;

/** Memory-bounded vertical PDF reading: ListView renders only visible/recycled pages. */
public class PdfContinuousActivity extends FinseqActivity {
 File cached;ParcelFileDescriptor fd;PdfRenderer renderer;LinearLayout root;TextView status;ListView list;
 @Override public void onCreate(Bundle b){super.onCreate(b);int policyId=getIntent().getIntExtra("policy_id",0);root=Ui.column(this);Ui.appHeader(root,this,"PDF · Continuous Scroll");status=Ui.sub(this,"Loading PDF…");root.addView(status);list=new ListView(this);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);Ui.run(this,()->{try{File f=ApiClient.pdf(this,policyId);if(!"pdf".equals(ApiClient.attachmentType(f)))throw new IOException("Continuous view is available for PDF files only");ParcelFileDescriptor x=ParcelFileDescriptor.open(f,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer r=new PdfRenderer(x);Ui.ui(this,()->{cached=f;fd=x;renderer=r;status.setText(renderer.getPageCount()+" pages · vertical continuous scroll");list.setAdapter(new PageAdapter());});}catch(Exception e){Ui.ui(this,()->status.setText("Could not open PDF: "+e.getMessage()));}});}
 class PageAdapter extends BaseAdapter {public int getCount(){return renderer==null?0:renderer.getPageCount();}public Object getItem(int p){return p;}public long getItemId(int p){return p;}public View getView(int p,View convert,android.view.ViewGroup parent){LinearLayout box;ImageView image;TextView label;if(convert instanceof LinearLayout){box=(LinearLayout)convert;image=(ImageView)box.getChildAt(1);label=(TextView)box.getChildAt(0);}else{box=Ui.card(PdfContinuousActivity.this);label=Ui.sub(PdfContinuousActivity.this,"");image=new ImageView(PdfContinuousActivity.this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);box.addView(label);box.addView(image,new LinearLayout.LayoutParams(-1,-2));}label.setText("Page "+(p+1)+" / "+getCount());try(PdfRenderer.Page page=renderer.openPage(p)){double scale=Math.min(1200.0/page.getWidth(),Math.sqrt(1800000.0/((double)page.getWidth()*page.getHeight())));int w=Math.max(1,(int)(page.getWidth()*scale)),h=Math.max(1,(int)(page.getHeight()*scale));Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.RGB_565);b.eraseColor(Color.WHITE);page.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);image.setImageBitmap(b);}catch(Throwable e){image.setImageDrawable(null);label.setText("Page "+(p+1)+" · preview unavailable");}return box;}}
 @Override protected void onDestroy(){super.onDestroy();try{if(renderer!=null)renderer.close();if(fd!=null)fd.close();}catch(IOException ignored){}if(cached!=null)cached.delete();}
}
